        raise ValueError("Invalid input coefficients")

    def f(x):
        return poly(xs, x)

    a = -1.0
    b = 1.0

    while abs(b - a) > 1e-6:
        mid = (a + b) / 2
        if f(mid) * f(a) < 0:
