def get_odd_collatz(n):
    def collatz_sequence(num):
        seq = []
        while num != 1:
            seq.append(num)
            if num % 2 == 0:
                num //= 2
            else:
                num = 3 * num + 1
        seq.append(1)  # Append the final number, which is always 1
        return seq

    odd_numbers = [num for num in collatz_sequence(n) if num % 2 != 0]
    return sorted(odd_numbers)

